<script setup>
const route = useRoute();
const { enabled: desktop } = useDesktop();
const { me } = useMe();
const { admin } = useAdmin();
const {unread}=useNotifications();
const active = computed(() => primaryDestination(route.path));
const links = [{ key: 'home', label: 'Overview', href: '/', icon: 'grid' }, { key: 'play', label: 'Play', href: '/play', icon: 'play' }, { key: 'leaderboard', label: 'Leaderboard', href: '/leaderboard', icon: 'trophy' }, { key: 'history', label: 'Match history', href: '/history', icon: 'clock' }];
const mobile = [...links.slice(0, 3), { key: 'you', label: 'You', href: '/settings', icon: 'user' }];
const signingOut = ref(false);
const failure = ref('');
async function signOut() { signingOut.value = true; try { await apiFetch('/auth/logout', { method: 'POST' }); window.location.assign('/'); } catch { failure.value = 'Could not sign out. Try again.'; signingOut.value = false; } }
</script>
<template>
<aside class="world-nav"><NuxtLink class="world-brand" to="/" aria-label="Ranked World home"><img src="/img/planet.png" width="32" height="32" alt="" /><span>Ranked<span class="world-brand__sub">WORLD</span></span></NuxtLink><nav aria-label="Main navigation" class="world-nav__links"><NuxtLink v-for="item in links" :key="item.key" :to="item.href" :aria-current="active === item.key ? 'page' : undefined" :class="{ selected: active === item.key }"><AppIcon :name="item.icon" />{{ item.label }}<AppIcon v-if="item.key === 'play'" name="arrowRight" class="world-nav__arrow" /></NuxtLink></nav><div class="world-nav__secondary"><NuxtLink v-if="admin" to="/admin" :class="{selected:route.path==='/admin'}"><AppIcon name="shield" />Admin</NuxtLink><NuxtLink to="/replays"><AppIcon name="play" />Replays</NuxtLink><NuxtLink to="/ranked"><AppIcon name="layers" />Ranked system</NuxtLink><NuxtLink to="/notifications" :class="{selected:route.path==='/notifications'}" :aria-current="route.path==='/notifications'?'page':undefined"><AppIcon name="bell" />Notifications<span v-if="unread" class="notification-count">{{ unread>99 ? '99+' : unread }}</span></NuxtLink><NuxtLink to="/launcher"><AppIcon name="download" />{{ desktop ? 'Game settings' : 'Launcher' }}</NuxtLink><a href="https://discord.gg/b4nxZCbdR4"><AppIcon name="discord" />Community<AppIcon name="external" /></a></div><div class="world-nav__bottom"><NuxtLink class="world-membership" to="/subscribe"><AppIcon name="sparkles" /><span>Membership</span><AppIcon name="arrowRight" /></NuxtLink><template v-if="me.user"><NuxtLink class="world-account" to="/me"><PlayerAvatar :name="me.user.username" :src="me.user.avatar" :discord-id="me.user.id" :size="32" /><span>{{ me.user.username }}<small>View your profile</small></span></NuxtLink><div class="world-account__actions"><NuxtLink to="/settings"><AppIcon name="settings" />Settings</NuxtLink><button :disabled="signingOut" @click="signOut"><AppIcon name="logOut" />Sign out</button></div><p v-if="failure" role="alert" class="meta bad">{{ failure }}</p></template><a v-else class="btn btn--brand" href="/sign-in"><AppIcon name="discord" />Sign in with Discord</a></div></aside><header class="world-mobile-head"><NuxtLink to="/" class="world-brand"><img src="/img/planet.png" width="25" height="25" alt="" />Ranked World</NuxtLink><NuxtLink v-if="admin" to="/admin" class="icon-btn" aria-label="Admin"><AppIcon name="shield" /></NuxtLink><NuxtLink to="/notifications" class="icon-btn mobile-notifications" :aria-label="unread ? `Notifications, ${unread} unread` : 'Notifications'"><AppIcon name="bell" /><span v-if="unread" class="notification-dot" /></NuxtLink><NuxtLink to="/settings" class="icon-btn" aria-label="Account settings"><AppIcon name="user" /></NuxtLink></header><nav class="world-mobile-nav" aria-label="Mobile navigation"><NuxtLink v-for="item in mobile" :key="item.key" :to="item.href" :class="{ selected: active === item.key }" :aria-current="active === item.key ? 'page' : undefined"><AppIcon :name="item.icon" /><span>{{ item.label }}</span></NuxtLink></nav>
</template>

<style scoped>
.notification-count{margin-left:auto;padding:2px 5px;border-radius:5px;background:var(--color-brand);color:var(--color-brand-inverted);font-size:11px;line-height:1.2}.mobile-notifications{margin-left:auto;position:relative}.notification-dot{position:absolute;top:5px;right:5px;width:6px;height:6px;border-radius:50%;background:var(--color-brand)}
</style>
